                d = abs(nx - target[0]) + abs(ny - target[1])
                cand = (d, dx, dy)
                if best is None or cand < best:
                    best = cand
        return [best[1], best[2]] if best is not None else [0, 0]

    def man(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    nearest = min(res_cells, key=lambda p: (man((sx, sy), p), p[0], p[1]))

